def prepare_conditioning(time_emb, class_emb):
    """Hybrid: additive conditioning (FiLM) + cross-attention.

    Combine time and class embeddings via addition, so ResBlocks receive
    class information via adaptive GroupNorm (FiLM). Cross-attention will
    further refine after each block.
    """
    return time_emb + class_emb


class ClassConditioner(nn.Module):
    """Cross-attention conditioning after each block (same as baseline)."""
    def __init__(self, channels, cond_dim):
        super().__init__()
        self.cross_attn = CrossAttentionLayer(channels, cond_dim, num_heads=4)

    def forward(self, h, class_emb):
        return self.cross_attn(h, class_emb)
